/usr/bin/bash -lc "perl -MList::Util=sum -e '
use strict; use warnings;
my "'$in="run_trace/intermediate/decoupler_count_matrix.tsv";
my $samples="run_trace/intermediate/decoupler_samples_metadata.tsv";
my $out="run_trace/intermediate/filtered_pseudobulk_counts.tsv";
my $facts="run_trace/intermediate/edger_factors.tsv";
open my $fh,"<",$in or die $!;
my $header=<$fh>; chomp $header;
my @cols=split /'"\\t/,"'$header,-1;
shift @cols;
my $N=@cols;
my @tot=(0)x$N;
my @rows;
while(<$fh>){ chomp; my @f=split /'"\\t/,"'$_,-1; my $gene=shift @f; for my $i (0..$#f){ $f[$i]=int($f[$i]+0.5); die "negative $gene'"\\n\" if "'$f[$i] < 0; $tot[$i]+=$f[$i]; } push @rows,[$gene,[@f]]; }
close $fh;
my @sorted=sort {$a<=>$b} @tot;
my $M = $N % 2 ? $sorted[int($N/2)] : ($sorted[$N/2-1]+$sorted[$N/2])/2;
my $S = int(10 + 0.7*($N-10)); $S++ if $S < 10 + 0.7*($N-10);
my $thr = 10 / $M * 1000000;
open my $of,">",$out or die $!;
print $of join("'"\\t\",\"gene\",@cols),\"\\n\";
my "'$kept=0;
for my $r (@rows){ my ($g,$a)=@$r; my $sum=0; my $ns=0; for my $i (0..$#$a){ $sum += $a->[$i]; my $cpm = $tot[$i] > 0 ? $a->[$i] / $tot[$i] * 1000000 : 0; $ns++ if $cpm >= $thr; } if($ns >= $S && $sum >= 1000){ print $of join("'"\\t\","'$g,@$a),"'"\\n\"; "'$kept++; } }
close $of;
open my $sf,"<",$samples or die $!;
my $sh=<$sf>; chomp $sh; my @sh=split /'"\\t/,"'$sh,-1; shift @sh;
my %meta;
while(<$sf>){ chomp; next unless length; my @f=split /'"\\t/,"'$_,-1; my $id=shift @f; my %h; @h{@sh}=@f; $meta{$id}='"\\%h; }
close "'$sf;
open my $ff,">",$facts or die $!;
print $ff join("'"\\t\",qw(sample disease cell_type individual)),\"\\n\";
for my "'$s (@cols){ die "missing sample metadata $s'"\\n\" unless exists "'$meta{$s}; my $m=$meta{$s}; my $d=$m->{disease}; $d = $d eq "COVID-19" ? "COVID19" : $d; my $ct=$m->{cell_type}; $ct =~ s/[ -]/_/g; my $ind=$m->{individual}; $ind =~ s/[ -]/_/g; print $ff join("'"\\t\","'$s,$d,$ct,$ind),"'"\\n\"; }
close "'$ff;
open my $lf,">","run_trace/filter_summary.txt" or die $!;
print $lf "N'"\\t"'$N'"\\nM\\t"'$M'"\\nS\\t"'$S'"\\nCPM_threshold\\t"'$thr'"\\nkept_genes\\t"'$kept'"\\n\";
print "'$lf "library_totals'"\\t\",join(\",\",@tot),\"\\n\";
close "'$lf;
print "N=$N M=$M S=$S threshold=$thr kept=$kept'"\\n\";
'"

